def now():return time.time()
def blob(b):
 if b is None:return None
 if type(b) is str:b=b.encode()
 out={'bytes':len(b),'sha256':sha(b),'base64':base64.b64encode(b).decode()}
 try:out['utf8']=b.decode('utf8')
 except UnicodeError:pass
 return out

def save():
