def req(ok,code):
 if not ok:raise Failure('F2B_RESEARCH_FAILED',code)

def valid_config(config):
 if config is None:return True
 if type(config) is not list or len(config)>2:return False
 seen=set()
 for x in config:
  if type(x) is not str or '=' not in x:return False
  k,v=x.split('=',1)
  if k in seen:return False
  seen.add(k)
  if k=='statement_timeout':
   if not re.fullmatch(r'[0-9]+(?:ms|s|min|h|d)?',v):return False
  elif k=='search_path':
   if not re.fullmatch(r'[a-z_][a-z0-9_]{0,62}(, [a-z_][a-z0-9_]{0,62})?',v):return False
   parts=v.split(', ')
   if len(set(parts))!=len(parts) or any(x.startswith('pg_') or x=='information_schema' for x in parts):return False
  else:return False
 return True

def research_role_rows(rows):
 # The sole accepted-domain shim. All original tuple/type/name/cardinality checks retained.
 ba._require(type(rows) is list and rows,'OWNED_ROLE_REPLAY_INCOMPLETE')
 names=[]
 for row in rows:
  ba._require(type(row) is list and len(row)==11,'OWNED_ROLE_REPLAY_INCOMPLETE')
  ba._restore_identifier(row[0]);names.append(row[0])
  ba._require(all(type(v) is bool for v in row[1:8]) and type(row[8]) is int and row[8]>=-1 and (row[9] is None or type(row[9]) is str),'OWNED_ROLE_REPLAY_INCOMPLETE')
  ba._require(valid_config(row[10]),'ROLE_FIDELITY_PROFILE_UNSUPPORTED')
 ba._require(len(set(names))==len(names),'OWNED_ROLE_REPLAY_INCOMPLETE')
 return rows

def global_settings_valid(rows,role_names):
 return type(rows) is list and all(type(x) is dict and x['setdatabase']=='0' and x['setrole']!='0' and x['role'] in role_names and valid_config(x['setconfig']) for x in rows)

