 boot=v['bootstrap'];owner=v['owner'];member=v['member'];grantor=v['grantor'];target=v['target']
 sql=f"CREATE ROLE postgres NOSUPERUSER NOLOGIN; CREATE ROLE anon NOLOGIN; CREATE ROLE authenticated NOLOGIN; CREATE ROLE service_role NOLOGIN;\n"
