# Manual read-only probes use their own receipt stream; never alter product calls.
def direct(args,data=None):
 started=now();p=subprocess.run(['docker',*args],input=data,stdout=subprocess.PIPE,stderr=subprocess.PIPE,env=mt.ENV,timeout=120,check=False)
 r={'kind':'DIRECT_READONLY_DIAGNOSTIC','variant':ACTIVE['key'] if ACTIVE else None,'argv':['docker',*args],'start':started,'end':now(),'stdin':blob(data),'stdout':blob(p.stdout),'stderr':blob(p.stderr),'returnCode':p.returncode}
 RESULT['receipts'].append(r)
 req(p.returncode==0,'READONLY_DIAGNOSTIC_FAILED');return p.stdout

def probe(container,user,sql,phase):
 raw=direct(['exec','-i','-e','PGOPTIONS=-c default_transaction_read_only=on',container,'psql','-XqAt','-h','/tmp','-U',user,'-d','postgres','-v','ON_ERROR_STOP=1','-v','VERBOSITY=verbose'],sql.encode())
 value=[json.loads(x) for x in raw.decode().splitlines() if x.strip()]
 r={'phase':phase,'container':container,'requestedUser':user,'query':blob(sql),'rawResult':blob(raw),'values':value,'canonicalSha256':sha(canonical(value)),'timestamp':now()}
 ACTIVE.setdefault('diagnosticMeasurements',[]).append(r);return value

def query(s,sql,label):
 value=ba._read_json(s,sql)
 ACTIVE.setdefault('oracleQueryResults',[]).append({'label':label,'query':blob(sql),'canonicalResult':value,'canonicalSha256':sha(canonical(value)),'timestamp':now()})
 return value

def oracle(s,catalog,label,normalize=False):
 out={'catalog':copy.deepcopy(catalog),'counts':ba._counts(s)}
 for key,sql in QUERIES.items():out[key]=query(s,sql,label+':'+key)
 if normalize:
  out['catalog']=ba._without_admin(out['catalog'],out['footprint'])
  out['roles']=ba._without_admin(out['roles'],out['footprint'])
 out['globalSettingsLogical']=[{k:r[k] for k in ['role','setdatabase','setconfig']} for r in out['globalSettings']]
 req(global_settings_valid(out['globalSettings'],[r[0] for r in out['roles']['roles']]),'DATABASE_SPECIFIC_OR_INVALID_ROLE_SETTINGS')
 out['dataSha256']=sha(canonical(out['data']));out['tableFedFunctionSha256']=sha(canonical(out['tableFedFunction']))
 return out

def observer(frame,event,arg):
 filename=frame.f_code.co_filename;name=frame.f_code.co_name;loc=frame.f_locals
 if not (filename.endswith('/backup_adapter.py') or filename.endswith('/maintenance_transport.py') or filename.endswith('/checks.py')):return observer
 d=mt._LOCAL_DIAGNOSTIC.get();phase=d.phase if d else None
 if name=='_docker':
  if event=='call':
   r={'kind':'OPERATIONAL_DOCKER','variant':ACTIVE['key'] if ACTIVE else None,'phase':phase,'operation':mt._LOCAL_OPERATION.get(),'argv':['docker',*loc['args']],'stdin':blob(loc.get('data')),'start':now()};FRAME_RECEIPTS[id(frame)]=r;RESULT['receipts'].append(r)
   if loc['args'][0]=='run' and '--name' in loc['args'] and ACTIVE:
    c=loc['args'][loc['args'].index('--name')+1];ACTIVE.setdefault('ownedContainerNames',[]).append(c)
    if phase=='E1':ACTIVE['destinationContainer']=c
  elif event=='return':
   r=FRAME_RECEIPTS.pop(id(frame),None)
   if r is not None:
    r['end']=now();p=loc.get('p')
    if p is not None:r.update(returnCode=p.returncode,stdout=blob(p.stdout),stderr=blob(p.stderr))
    else:r['returnCode']='NOT_AVAILABLE'
 elif name=='_exchange':
  if event=='call':
   r={'kind':'OPERATIONAL_SESSION_SQL','variant':ACTIVE['key'] if ACTIVE else None,'phase':phase,'argv':loc['self']._proc.args,'sql':blob(loc['sql']),'start':now()};FRAME_RECEIPTS[id(frame)]=r;RESULT['receipts'].append(r)
  elif event=='return':
   r=FRAME_RECEIPTS.pop(id(frame),None)
   if r is not None:r.update(end=now(),protocolStrippedResult=blob(arg) if type(arg) is str else None,success=type(arg) is str,ackLine=loc.get('line'),errorCount=loc['self']._errors)
 elif name=='__init__' and event=='call' and loc.get('self').__class__ is mt._Session:
  RESULT['receipts'].append({'kind':'OPERATIONAL_SESSION_START','variant':ACTIVE['key'] if ACTIVE else None,'phase':phase,'argv':loc['argv'],'timestamp':now()})
 elif name=='_staged_plpgsql' and ACTIVE:
  if event=='call':
   t=loc['t'];c=t.container
   ACTIVE['preStagedRoleState']=probe(c,mt.OWNED_RESTORE_ADMIN,ba.ROLE_STATE_SQL,'POST_E3_ROLE_STATE')[0]
   # No monkeypatch; diagnostic subprocess calls return no data into recovery.
   baseline=FRESH_SQL
   seq='BEGIN READ ONLY;\n'+baseline+'\nSET ROLE '+qi(ACTIVE['owner'])+';\n'+baseline+'\nRESET ROLE;\n'+baseline+'\nROLLBACK;'
   ACTIVE['setRoleDiagnostic']=probe(c,mt.OWNED_RESTORE_ADMIN,seq,'POST_E3_PRE_STAGED_SAME_SESSION')
   ACTIVE['preE4FreshLogin']=probe(c,ACTIVE['owner'],FRESH_SQL,'POST_E3_PRE_E4_FRESH_LOGIN')[0]
  elif event=='return' and type(arg) is dict:ACTIVE['stagedReceipt']=copy.deepcopy(arg)
 elif name=='observe' and event=='return' and ACTIVE and phase in ('E5','E7') and type(arg) is dict:
  # Only read-only destination measurement interception; return value untouched.
  ACTIVE['destination'+phase]=oracle(loc['session'],arg,'DESTINATION_'+phase,True)
  c=ACTIVE['destinationContainer']
  ACTIVE['freshLogin'+phase]=probe(c,ACTIVE['owner'],FRESH_SQL,phase+'_FRESH_LOGIN')[0]
 elif name=='_acl_supplement' and event=='return' and ACTIVE and type(arg) is list:
  ACTIVE['supplementSql']=arg;ACTIVE['supplementSqlSha256']=sha('\n'.join(arg).encode())
 elif name=='_derive_roles' and event=='return' and ACTIVE and type(arg) is tuple:
  ACTIVE.setdefault('derivations',[]).append({'raw':blob(loc['raw']),'derived':blob(arg[0]),'receipt':copy.deepcopy(arg[1])})
 elif name=='_tool' and event=='return' and ACTIVE and type(arg) is bytes:
  ACTIVE.setdefault('captures',[]).append({'tool':loc['tool'],'args':loc['args'],'raw':blob(arg)})
 if event=='call' and name in CODE_BINDINGS and filename.endswith('/backup_adapter.py'):
  RESULT['functionObservations'].append({'variant':ACTIVE['key'] if ACTIVE else None,'function':name,'phase':phase,'event':'call','timestamp':now()})
 if event=='exception' and ACTIVE:
  et,ev,tb=arg
  if isinstance(ev,Failure):ACTIVE.setdefault('exceptionObservations',[]).append({'function':name,'phase':phase,'code':ev.code,'state':ev.state,'line':frame.f_lineno})
 return observer

