def compare_variant(v):
 src=v['sourceOracle'];dst=v.get('destinationE7');req(dst is not None,'FINAL_DESTINATION_MEASUREMENT_MISSING')
 fields=['catalog','roles','counts','locale','globalSettingsLogical','plpgsql','databaseAcl','acl','owners','data','sequence','tableFedFunction','objectCounts','footprint','unsupportedFamilies']
 gates={k:canonical(src[k])==canonical(dst[k]) for k in fields}
 gates['freshLoginFinal']=v['sourceFreshLogin']==v['freshLoginE7']
