CREATE FUNCTION app.render_label(p_id integer) RETURNS text LANGUAGE plpgsql STABLE AS $$DECLARE r record; BEGIN SELECT s.label,s.note,s.amount INTO STRICT r FROM app.owner_probe AS s WHERE s.id=p_id; RETURN r.label||':'||coalesce(r.note,'<null>')||':'||r.amount::text; END;$$;
